const DOCUMENTOS = ["I - Histórico escolar ou atestado de transferência;","II – RG e CPF do pai, da mãe ou do responsável legal;","III - Certidão de nascimento ou casamento do estudante;","IV – RG e CPF do estudante;","V - Fatura, atualizada, de Energia Elétrica da residência dos pais/responsáveis;","VI - Tipo sanguíneo e fator Rh do estudante;","VII - cartão de vacinação atualizado do estudante (de acordo com a Lei Estadual n.º 10.736, de 09 de agosto de 2018);","VIII - Atestado médico oftalmológico ou avaliação técnica de optometria do estudante, apenas para o Ensino Fundamental (de acordo com a Lei nº 11.851, de 27 de julho de 2022);","IX - Documento comprobatório do estudante pertencente ao Público Alvo da Educação Especial (PAEDE), caso seja aplicável;","X - Documento oficial de guarda do estudante, quando necessário;","XI - Termo de Consentimento para Tratamento de Dados Pessoais;","XII – Declaração Vacinal do Posto de Saúde;"];
const LOGO_ESTADO = "data:image/png;base64,";
