const CAMPOS_ALUNO=['tcAluno','tcNascimento','tcCPFAluno','tcResponsavel','tcCPFResp','tcRGResp','tcTurma','tcTurno','tcMae','tcPai','tcEndereco','tcCidadeAluno','tcTelefone','tcEmail'];
function limparAluno() {
    for(const id of CAMPOS_ALUNO) if($id(id)) $id(id).value='';
    document.querySelectorAll('[name="tcDocumento"]').forEach(el=>el.checked=false);
    if($id('tcImprimir')) $id('tcImprimir').disabled=true;
}
async function carregarDados() {
    if(carregando) { aviso('Aguarde a consulta em andamento; os dados do novo código serão carregados em seguida.'); return; }
    const codigo=campo('vGEDALUCOD');
    if(!/^\d+$/.test(codigo)||Number(codigo)<=0) { aviso('Informe um código de aluno válido.',true); return; }
    carregando=true; const pedido=++sequencia; codigoCarregado='';
    $id('tcImprimir').disabled=true; $id('tcCarregar').disabled=true; aviso('Consultando cadastro e matrícula do aluno…');
    try {
        const pessoa=(async()=>{
            const iframe=$id(ID_IFRAME_PESSOAL);
            await carregarIframe(iframe,urlGED(`hwtmgedaluno.aspx?${encodeURIComponent(codigo)},,HWMConAluno,DSP,1,0`));
            return extrairCadastro(iframe.contentDocument);
        })();
        const [cadastro,matricula]=await Promise.all([pessoa,consultarMatriculaVigente(codigo)]);
        if(pedido!==sequencia || campo('vGEDALUCOD')!==codigo || !modoTermos()) return;
        dadosCadastro=cadastro;
        const valores={tcAluno:cadastro.aluno,tcNascimento:cadastro.nascimento,tcCPFAluno:cadastro.cpfAluno,
            tcResponsavel:cadastro.responsavel,tcCPFResp:cadastro.cpfResponsavel,tcMae:cadastro.mae,tcPai:cadastro.pai,
            tcEndereco:cadastro.endereco,tcCidadeAluno:cadastro.municipio,tcTelefone:cadastro.telefone,tcEmail:cadastro.emailResponsavel,
            tcTurma:matricula?.turma||'',tcTurno:matricula?.turno||'',tcRGResp:''};
        for(const [id,valor] of Object.entries(valores)) $id(id).value=valor;
        if(matricula?.anoLetivo) $id('tcAno').value=matricula.anoLetivo;
        codigoCarregado=codigo;
        $id('tcImprimir').disabled=false;
        aviso('Dados carregados. Confira antes de imprimir.'+(!matricula?' Turma e período não encontrados: preencha se necessário.':''));
        atualizarTipo();
    } catch(erro) {
        if(pedido===sequencia) { limparAluno(); aviso(erro.message || 'Não foi possível carregar os dados.',true); }
    } finally {
        carregando=false; $id('tcCarregar').disabled=false;
        if(pedido!==sequencia && modoTermos() && /^\d+$/.test(campo('vGEDALUCOD')) && Number(campo('vGEDALUCOD'))>0) setTimeout(carregarDados,0);
    }
}
function atualizarTipo() {
    if(!$id('tcDocumentos')) return;
    $id('tcDocumentos').style.display=campo('tcTipo')==='documentos'?'':'none';
    const idade=idadeCompleta(campo('tcNascimento'),campo('tcEmissao'));
    $id('tcIdade').textContent=idade===null?'Informe uma data de nascimento válida para definir o termo de imagem.':
        `${idade} anos na data de emissão — termo de imagem para ${idade>=18?'maior':'menor'} de idade.`;
}
function obterDadosFormulario() {
    return {...dadosCadastro,aluno:campo('tcAluno'),cpfAluno:campo('tcCPFAluno'),nascimento:campo('tcNascimento'),
        responsavel:campo('tcResponsavel'),cpfResponsavel:campo('tcCPFResp'),rgResponsavel:campo('tcRGResp'),
        mae:campo('tcMae'),pai:campo('tcPai'),endereco:campo('tcEndereco'),municipio:campo('tcCidadeAluno'),
        municipioCabecalho:campo('tcMunicipio'),telefonesResponsavel:[campo('tcTelefone')].filter(Boolean),
        emailResponsavel:campo('tcEmail'),escola:campo('tcEscola'),anoLetivo:campo('tcAno'),
        turma:campo('tcTurma'),turno:campo('tcTurno'),prazo:campo('tcPrazo'),emissao:campo('tcEmissao'),dre:campo('tcDRE'),
        assinante:campo('tcAssinante'),documentos:Array.from(document.querySelectorAll('[name="tcDocumento"]:checked'),el=>Number(el.value))};
}
function validarEmissao(tipo,d) {
    if(!d.aluno || !d.escola || !d.municipioCabecalho || !lerData(d.emissao)) throw Error('Confira o nome do aluno, a escola, o município e a data de emissão.');
    const idade=idadeCompleta(d.nascimento,d.emissao);
    if(tipo==='imagem') tipo=tipoImagem(d.nascimento,d.emissao);
    if(tipo==='familyMinor' && (idade===null || idade>=18)) throw Error('O compromisso familiar deste modelo é para menor de idade. Confira o nascimento.');
    if(['imgMinor','familyMinor','authMatricula'].includes(tipo) && !d.responsavel) throw Error('Informe o nome do responsável.');
    if(tipo==='familyMinor' && (!d.cpfResponsavel || !d.rgResponsavel)) throw Error('Informe o CPF e o RG do responsável para o compromisso familiar.');
    if(tipo==='documentos') {
        if(!d.documentos.length || d.documentos.some(i=>!Number.isInteger(i)||i<0||i>=DOCUMENTOS.length)) throw Error('Marque pelo menos um documento pendente.');
        if(!lerData(d.prazo) || lerData(d.prazo)<lerData(d.emissao)) throw Error('Informe um prazo de entrega igual ou posterior à data de emissão.');
        if(!d.turma || !d.turno || !/^\d{4}$/.test(d.anoLetivo)) throw Error('Informe turma, período e ano letivo.');
        if(d.assinante==='aluno' && (idade===null || idade<18)) throw Error('Para assinatura do próprio aluno, confirme que ele tem 18 anos ou mais.');
        if(d.assinante==='responsavel' && (!d.responsavel || !d.cpfResponsavel)) throw Error('Informe nome e CPF do responsável.');
        if(d.assinante==='aluno' && !d.cpfAluno) throw Error('Informe o CPF do aluno.');
    }
    return tipo;
}
function gerarDocumentosPendentes(d) {
    const h=escapeHtml, resp=d.assinante!=='aluno';
    const compromisso=resp?`Eu, <strong>${h(d.responsavel)}</strong>, CPF: <strong>${h(d.cpfResponsavel)}</strong>, abaixo assinado, responsável pelo(a) aluno(a) <strong>${h(d.aluno)}</strong>`:
        `Eu, <strong>${h(d.aluno)}</strong>, CPF: <strong>${h(d.cpfAluno)}</strong>, abaixo assinado, aluno(a)`;
    const prazo=lerData(d.prazo).toLocaleDateString('pt-BR');
    return `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8"><title>Termo de compromisso para entrega de documentos</title><style>
        @page{size:A4;margin:12mm 17mm 12mm 23mm}*{box-sizing:border-box}body{font:11pt/1.3 Arial,sans-serif;color:#000;margin:0;background:white}.pendentes{max-width:170mm;margin:auto}header{display:flex;align-items:center;justify-content:space-between;gap:10mm;min-height:25mm}header .estado{width:64mm}header .escola{width:24mm}.instituicao{text-align:center;font-size:10pt;line-height:1.3;margin:3mm 0 8mm}h1{text-align:center;font-size:11pt;margin:0 0 7mm}p{text-align:justify;margin:0 0 5mm}.docs{font-size:10.5pt;line-height:1.25}.doc{display:flex;gap:3mm;margin:2mm 0;break-inside:avoid}.check{font-family:Arial;flex:none;white-space:pre}.data{text-align:right;margin-top:8mm}.assinatura{text-align:center;margin-top:14mm;break-inside:avoid}.assinatura span{display:block;border-top:1px solid #000;width:110mm;margin:0 auto 2mm}@media screen{body{background:#eee;padding:12mm}.pendentes{background:white;padding:10mm;max-width:190mm;box-shadow:0 1px 6px #bbb}}</style></head><body><main class="pendentes">
        <header><img class="estado" src="${LOGO_ESTADO}" alt="Governo de Mato Grosso e SEDUC">${/onze de mar[cç]o/i.test(d.escola)?`<img class="escola" src="${LOGO_ESCOLA}" alt="Escola Estadual Onze de Março">`:''}</header>
        <div class="instituicao">${h(d.dre)}<br><strong>${h(d.escola)}</strong></div>
        <h1>TERMO DE COMPROMISSO PARA ENTREGA DE DOCUMENTOS</h1>
        <p>${compromisso} matriculado(a) na turma: <strong>${h(d.turma)}</strong> período: <strong>${h(d.turno)}</strong>, ano letivo de <strong>${h(d.anoLetivo)}</strong> na <strong>${h(d.escola)}</strong>, estando ciente que no ato da matrícula, firmo o compromisso, no sentido de entregar na secretaria da referida escola todos os documentos exigidos para a matrícula, conforme a PORTARIA Nº 755/2025/GS/SEDUC/MT (Art 9º, § 1º) e também em atendimento ao documento de Notificação Recomendatória, SIMP:006805-012/2022 da 1ª PROMOTORIA DE JUSTIÇA CÍVEL- CÁCERES-MT DO MPMT, até o dia <strong>${h(prazo)}</strong>. Firmo o presente TERMO DE COMPROMISSO, e, em sinal de anuência, declaro estar ciente que, em caso de não cumprimento, a falta de algum documento poderá causar algum impedimento na vida administrativa do(a) aluno(a).</p>
        <strong>DOCUMENTOS FALTANTES:</strong><div class="docs">${DOCUMENTOS.map((doc,i)=>`<div class="doc"><span class="check">[${d.documentos.includes(i)?'X':' '}]</span><span>${h(doc)}</span></div>`).join('')}</div>
        <p class="data">${h(d.municipioCabecalho)}-MT, ${h(lerData(d.emissao).toLocaleDateString('pt-BR',{day:'numeric',month:'long',year:'numeric'}))}</p>
        <div class="assinatura"><span></span>Assinatura do(a) aluno(a) ou responsável.</div></main></body></html>`;
}
function gerarTermo(tipo,d,escola={}) {
    tipo=validarEmissao(tipo,d);
    if(tipo==='documentos') return gerarDocumentosPendentes(d);
    if(tipo==='imgMinor') return buildImageMinorTerm(d);
    if(tipo==='imgMajor') return buildImageMajorTerm(d);
    if(tipo==='familyMinor') return buildFamilyMinorTerm(d,d.rgResponsavel);
    if(tipo==='authMatricula') return buildAuthMatriculaTerm(d);
    if(tipo==='data') return buildDataTerm(d,escola);
    throw Error('Tipo de termo não reconhecido.');
}
function imprimirTermo() {
    try {
        if(carregando || !codigoCarregado || campo('vGEDALUCOD')!==codigoCarregado) throw Error('Carregue os dados do aluno selecionado antes de imprimir.');
        const dados=obterDadosFormulario();
        const escola={enderecoEscola:campo('tcEnderecoEscola'),telefoneEscola:campo('tcTelEscola'),emailEscola:campo('tcEmailEscola')};
        if(campo('tcTipo')==='data' && Object.values(escola).some(v=>!v)) throw Error('Complete endereço, telefone e e-mail da escola em Dados complementares.');
        const html=gerarTermo(campo('tcTipo'),dados,escola);
        const janela=window.open('','_blank');
        if(!janela) throw Error('Permita a abertura da janela de impressão no navegador.');
        janela.document.open(); janela.document.write(html); janela.document.close(); janela.opener=null;
        const barra=janela.document.createElement('div');
        barra.className='tc-nao-imprimir'; barra.style.cssText='position:sticky;top:0;padding:12px;background:#e8eef5;font:14px Arial;z-index:100';
        barra.textContent='Confira o documento antes de imprimir. ';
        const botao=janela.document.createElement('button'); botao.textContent='Imprimir / Salvar em PDF'; botao.style.cssText='padding:8px 16px;cursor:pointer';
        botao.addEventListener('click',()=>janela.print()); barra.appendChild(botao); janela.document.body.prepend(barra);
        const style=janela.document.createElement('style'); style.textContent='@media print{.tc-nao-imprimir{display:none!important}}'; janela.document.head.appendChild(style);
        aviso('Documento aberto para conferência e impressão.');
    } catch(erro) { aviso(erro.message,true); }
}
function iniciar() {
    if(!modoTermos()) return;
    if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',()=>adaptarPagina(),{once:true});
    else adaptarPagina();
}
window.addEventListener('hashchange',()=>{
    if(!/\/ged\/hwcmatriculasaluno\.aspx$/i.test(location.pathname)) return;
    if(montada || modoTermos()) location.reload();
});
iniciar();

